tasks.solution:
def threshold_cost(actual, scores, t, fp_cost, fn_cost):
    cost = 0
    for y,s in zip(actual,scores):
        if s >= t and y == 0:
            cost += fp_cost
        elif s < t and y == 1:
            cost += fn_cost
    return cost

